#include <cstddef>
#include <iostream>
#include <utility>

class Buffer
{
public:
    explicit Buffer(std::size_t size) : m_data{new std::byte[size]{}}, m_size{size} {}
    ~Buffer() { delete[] m_data; }
    std::size_t size() const { return m_size; }

private:
    std::byte* m_data{};
    std::size_t m_size{};
};

int main()
{
    Buffer a{16};
    std::cout << a.size() << '\n';
}
